            //
            aWandererB = aWandererB ^ ((RotL64(aIngress, 26U) + aOrbiterJ) + RotL64(aOrbiterE, 58U));
            aWandererE = aWandererE + ((((RotL64(aCross, 41U) + RotL64(aOrbiterJ, 5U)) + aOrbiterF) + RotL64(aCarry, 23U)) + aPhaseAWandererUpdateSaltE[((aIndex + 6U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aScatter, 35U) + RotL64(aOrbiterF, 21U)) + aOrbiterA);
            aWandererI = aWandererI + ((((RotL64(aPrevious, 51U) + aOrbiterE) + RotL64(aOrbiterD, 41U)) + RotL64(aCarry, 35U)) + aPhaseAWandererUpdateSaltC[(((31U - aIndex) + 19U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 19U) + aOrbiterA) + RotL64(aOrbiterD, 51U));
