            aCross = (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 6758U)) & S_BLOCK1], 27U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 6136U)) & S_BLOCK1], 48U));
            aCross ^= RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 9365U)) & S_BLOCK1], 35U);
