            //
            aScatter = (RotL64(aIngress, 60U) + RotL64(aCross, 23U)) + (RotL64(aPrevious, 43U) ^ RotL64(aCarry, 11U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterA = (aWandererB + RotL64(aCross, 43U)) + 0x4ED84C33E6F65D0CULL;
            aOrbiterF = (((aWandererK + RotL64(aIngress, 35U)) + RotL64(aCarry, 3U)) + 0x3651EC7232F1B166ULL) + aPhaseBOrbiterAssignSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterC = ((aWandererJ + RotL64(aPrevious, 58U)) + RotL64(aCarry, 51U)) + 0x969D52C2BFBF11BEULL;
            aOrbiterB = (((aWandererF + RotL64(aScatter, 3U)) + RotL64(aCarry, 37U)) + 0xD3B9F315156DC419ULL) + aPhaseBOrbiterAssignSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterE = (aWandererG + RotL64(aPrevious, 51U)) + 0xDFBE10A774C8C6B0ULL;
            aOrbiterD = (aWandererE + RotL64(aIngress, 29U)) + 0x536A7C3C380D7C96ULL;
            aOrbiterG = (aWandererI + RotL64(aCross, 19U)) + 0x6B5BA9CFBAB75CD0ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0xEB4097E479B335EEULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0x6E48C8B65D51F779ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xAB922F6D012B8D31ULL), 21U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x0C632E064A07A513ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x6ED2292AEB9A524CULL;
            aOrbiterE = RotL64((aOrbiterE * 0x742227A123860571ULL), 5U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0x4CF6C879CDBEA076ULL) + aPhaseBOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterD) ^ 0xC91CAF5B961F25A3ULL) ^ aPhaseBOrbiterUpdateSaltF[((aIndex + 10U)) & S_SALT1];
