            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x3F09632607569AD6ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0xC74905EE5AEE7DAAULL;
            aOrbiterB = RotL64((aOrbiterB * 0x4CB84F6B62650BBDULL), 57U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0xAC2B4D7926239F69ULL) + aPhaseBOrbiterUpdateSaltC[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x7C5E10558C5E33DDULL;
            aOrbiterG = RotL64((aOrbiterG * 0x5573E4F8B0D5BCDBULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x29745AA81AA299D6ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x1666CDE4E2D6793FULL;
            aOrbiterF = RotL64((aOrbiterF * 0xBF9151CF374D2783ULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xC365A66ADF451CC9ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterF) ^ 0xD1C63CB203284668ULL) ^ aPhaseBOrbiterUpdateSaltD[((aIndex + 15U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x95836B1F91AAF111ULL), 35U);
            //
