            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x09EC7612ACCA050FULL) ^ aPhaseDOrbiterUpdateSaltD[((aIndex + 6U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x5E3E55C4F4B3CBF9ULL), 27U);
