            aCross = (RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 17705U)) & S_BLOCK1], 51U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 21893U)) & S_BLOCK1], 3U));
