            //
            aOrbiterH = ((aWandererC + RotL64(aScatter, 57U)) + 0x4C5EF03971105DA3ULL) + aPhaseAOrbiterAssignSaltE[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterC = ((aWandererI + RotL64(aCross, 13U)) + 0x1A1A15D8EC28D922ULL) + aPhaseAOrbiterAssignSaltF[((aIndex + 21U)) & S_SALT1];
            aOrbiterK = (aWandererJ + RotL64(aIngress, 3U)) + 0xF3B7BBABF20454F8ULL;
            aOrbiterF = (aWandererE + RotL64(aPrevious, 30U)) + 0xF15F8C4A1C5DC064ULL;
            aOrbiterA = ((aWandererA + RotL64(aScatter, 51U)) + RotL64(aCarry, 43U)) + 0x6F1F95E78111E6FDULL;
            aOrbiterI = ((aWandererK + RotL64(aIngress, 23U)) + RotL64(aCarry, 29U)) + 0x7D891F19CB2411FAULL;
            aOrbiterG = ((aWandererH + RotL64(aPrevious, 37U)) + RotL64(aCarry, 57U)) + 0x849AB7A1D1B630A0ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x7085A9A5A1D0D87AULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x0E54D51A3491B0DEULL;
            aOrbiterK = RotL64((aOrbiterK * 0x204BC9A2BC493AC3ULL), 51U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0x96C64CAC198B80DBULL) + aPhaseAOrbiterUpdateSaltC[(((31U - aIndex) + 24U)) & S_SALT1];
