            //
            aOrbiterA = ((aOrbiterA + aOrbiterI) + 0xCD968F4814D28266ULL) + aPhaseAOrbiterUpdateSaltB[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0xACBBF08BBCE1AF1AULL;
            aOrbiterG = RotL64((aOrbiterG * 0x5CC9B43E105E2D57ULL), 21U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterG) + 0x948CF5776D363BF9ULL) + aPhaseAOrbiterUpdateSaltE[((aIndex + 19U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x9EA053B86CB82476ULL;
