            aOrbiterG = (aOrbiterG + aOrbiterH) + 0xA4668B5781EF4251ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x054AB607D7E859C9ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xC3C7F65343E4B973ULL), 3U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xABE8C55E3765B8E9ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0xD84069452621A314ULL) ^ aPhaseAOrbiterUpdateSaltA[((aIndex + 14U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xA0B0A85CB59950A7ULL), 27U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x831B8685321D6112ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x4C4EBC32041D0D97ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xCF27471B04A1ABA7ULL), 57U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterK, 21U);
