            //
            aWandererA = aWandererA ^ ((RotL64(aScatter, 37U) + aOrbiterC) + RotL64(aOrbiterH, 43U));
            aWandererK = aWandererK + ((((RotL64(aCross, 5U) + aOrbiterC) + RotL64(aOrbiterK, 37U)) + RotL64(aCarry, 39U)) + aPhaseAWandererUpdateSaltC[((aIndex + 15U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 43U) + aOrbiterG) + RotL64(aOrbiterI, 11U));
