            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0x9917F3B603348A9BULL) + aPhaseCOrbiterUpdateSaltF[((aIndex + 24U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0xB96E0B45FB056CCFULL;
