            //
            aOrbiterA = ((aOrbiterA + aOrbiterD) + 0x6270D706F71EA9DCULL) + aPhaseCOrbiterUpdateSaltE[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0x6FB6507C5A6252EEULL;
            aOrbiterH = RotL64((aOrbiterH * 0x2B32856F2883B493ULL), 29U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x9022DE5A5EAD2DFCULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0x909B70929AB7DAF6ULL) ^ aPhaseCOrbiterUpdateSaltD[((aIndex + 23U)) & S_SALT1];
